import { apiFetch } from './http';

/**
 * Adapter between the hooks generated by Orval and {@link apiFetch}, so every generated call carries the
 * session token and the interface language (API-12, IMP-04).
 *
 * @param url - path built by the generated code
 * @param init - fetch options built by the generated code
 * @returns the parsed body
 */
export const orvalMutator = <T>(url: string, init?: RequestInit): Promise<T> => apiFetch<T>(url, init);

export default orvalMutator;
